/*
 * init()
 */
scwin.fn_init = function() {
    //setObjectValue(edt_Date,vCurDate);
    scwin.fn_searchCode();
    scwin.fn_searchCombo();
};
scwin.fn_searchCode = function() {
    /*
    03905  지수산출기관코드	
    03902  지수레버리지인버스구분코드
    */
    var arrCid = [{
        cid: "IDX_CALC_INST_CD",
        cnm: "cmb_IDX_CALC_INST_CD"
    }, {
        cid: "IDX_LVRG_INVRS_TP_CD",
        cnm: "cmb_IDX_LVRG_INVRS_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='IDX_CALC_INST_CD','IDX_LVRG_INVRS_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^ 전체";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};



/* 기초시장 및 기초 자산*/
scwin.fn_searchCombo = function() {
    /* 기초시장 대분류 */
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=ETF_ETN_MKT_TP_CD_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstsrch.mkt.tp.cd.L.select.list.condition";
    dts_MKT_TP_CD_L.DataID = encodeURI(url);
    dts_MKT_TP_CD_L.reset();
    dts_MKT_TP_CD_L.insertRow(0);
    dts_MKT_TP_CD_L.setCellData(1, "IDX_MKT_CLSS_ID", "");
