/*
 기초지수 조회
*/
scwin.fn_list_sync = function() {
    // 기초시장 대/중/소 미선택시 
    if (dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") == "" &&
        dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") == "" &&
        dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") == "") {
        scwin.gIDX_MKT_CLSS_ID = "______";
    }

    // 기초시장 대분류만 선택시
    if (dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") != "" &&
        dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") == "" &&
        dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") == "") {
        scwin.gIDX_MKT_CLSS_ID = dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID").substr(0, 2) + "____";
    }

    // 기초시장 대분류 미선택
    //               중분류만 선택시 
    if (dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") == "" &&
        dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") != "" &&
        dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") == "") {
        scwin.gIDX_MKT_CLSS_ID = dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID").substr(0, 4) + "__";
    }

    // 기초시장 대분류 미선택
    //               중분류 미선택
    //               소분류만 선택시
    if (dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") == "" &&
        dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") == "" &&
        dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") != "") {
        scwin.gIDX_MKT_CLSS_ID = dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID");
    }

    // 기초시장 대분류 선택
    //               중분류 선택 
    //			소분류 미선택시
    if (dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") != "" &&
        dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") != "" &&
        dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") == "") {
        scwin.gIDX_MKT_CLSS_ID = dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID").substr(0, 4) + "__";
    }


    // 기초시장 대분류 미선택
    //               중분류 선택시
    //               소분류 선택시
    if (dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") == "" &&
        dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") != "" &&
        dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") != "") {
        scwin.gIDX_MKT_CLSS_ID = dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID");
    }

    // 기초시장 대분류 선택시
    //               중분류 선택시
    //               소분류 선택시
    if (dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") != "" &&
        dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") != "" &&
        dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") != "") {
        scwin.gIDX_MKT_CLSS_ID = dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID");
    }

    ///////////////////////////////////////////////////////////////////////////////////////////////////////////

    // 기초자산 대/중/소 미선택시 
    if (dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") == "" &&
        dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") == "" &&
        dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID") == "") {
        scwin.gIDX_ASST_CLSS_ID = "______";
    }

    // 기초자산 대분류만 선택시
    if (dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") != "" &&
        dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") == "" &&
        dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID") == "") {
        scwin.gIDX_ASST_CLSS_ID = dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID").substr(0, 2) + "____";
    }

    // 기초자산 대분류 미선택
    //               중분류만 선택시 
    if (dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") == "" &&
        dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") != "" &&
        dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID") == "") {
        scwin.gIDX_ASST_CLSS_ID = dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID").substr(0, 4) + "__";
    }

    // 기초자산 대분류 미선택
    //               중분류 미선택
    //               소분류만 선택시
    if (dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") == "" &&
        dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") == "" &&
        dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID") != "") {
        scwin.gIDX_ASST_CLSS_ID = dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID");
    }

    // 기초자산 대분류 선택
    //               중분류 선택 
    //			소분류 미선택시
    if (dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") != "" &&
        dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") != "" &&
        dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID") == "") {
        scwin.gIDX_ASST_CLSS_ID = dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID").substr(0, 4) + "__";
    }


    // 기초자산 대분류 미선택
    //               중분류 선택시
    //               소분류 선택시
    if (dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") == "" &&
        dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") != "" &&
