    // 기초자산 대분류 선택시
    //               중분류 선택시
    //               소분류 선택시
    if (dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") != "" &&
        dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") != "" &&
        dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID") != "") {
        scwin.gIDX_ASST_CLSS_ID = dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID");
    }


    /*		
    		// 현업이 중분류 단위로 검색 요구로 주석

    		if(dts_MKT_TP_CD_L.NameValue(dts_MKT_TP_CD_L.RowPosition,"IDX_MKT_CLSS_ID") == "" ) {
    			gIDX_MKT_CLSS_ID = "______";
    		} else {
    			if(dts_MKT_TP_CD_M.NameValue(dts_MKT_TP_CD_M.RowPosition,"IDX_MKT_CLSS_ID") == "" ) {
    				gIDX_MKT_CLSS_ID = dts_MKT_TP_CD_L.NameValue(dts_MKT_TP_CD_L.RowPosition,"IDX_MKT_CLSS_ID").substr(0,2)+"____";
    			} else {
    				if(dts_MKT_TP_CD_S.NameValue(dts_MKT_TP_CD_S.RowPosition,"IDX_MKT_CLSS_ID") == ""  ) {
    						gIDX_MKT_CLSS_ID = dts_MKT_TP_CD_M.NameValue(dts_MKT_TP_CD_M.RowPosition,"IDX_MKT_CLSS_ID").substr(0,4)+"__";
    				} else {
    					gIDX_MKT_CLSS_ID = dts_MKT_TP_CD_S.NameValue(dts_MKT_TP_CD_S.RowPosition,"IDX_MKT_CLSS_ID");				
    				}
    			}
    		}

    		if(dts_ULY_TP_CD_L.NameValue(dts_ULY_TP_CD_L.RowPosition,"IDX_ASST_CLSS_ID") == "" ) {
    			gIDX_ASST_CLSS_ID = "______";
    		} else {
    			if(dts_ULY_TP_CD_M.NameValue(dts_ULY_TP_CD_M.RowPosition,"IDX_ASST_CLSS_ID") == "" ) {
    				gIDX_ASST_CLSS_ID = dts_ULY_TP_CD_L.NameValue(dts_ULY_TP_CD_L.RowPosition,"IDX_ASST_CLSS_ID").substr(0,2)+"____";
    			} else {
    				if(dts_ULY_TP_CD_S1.NameValue(dts_ULY_TP_CD_S1.RowPosition,"IDX_ASST_CLSS_ID") == ""  ) {
    						gIDX_ASST_CLSS_ID = dts_ULY_TP_CD_M.NameValue(dts_ULY_TP_CD_M.RowPosition,"IDX_ASST_CLSS_ID").substr(0,4)+"__";
    				} else {
    					gIDX_ASST_CLSS_ID = dts_ULY_TP_CD_S1.NameValue(dts_ULY_TP_CD_S1.RowPosition,"IDX_ASST_CLSS_ID");				
    				}
    			}
    		}
    */
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneralForDynamicName&outputMessageId=ETF_ETN_BYTP_BAS_IDX_ADM_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstproc.newlst.select.etpbasidx.list.condition" + "&{P}V_IDX_CALC_INST_CD=" + $c.stf.getObjectValue(cmb_IDX_CALC_INST_CD) + // 지수산출기관
        "&{P}V_IDX_MKT_CLSS_ID=" + scwin.gIDX_MKT_CLSS_ID + // 기초시장
        "&{P}V_IDX_ASST_CLSS_ID=" + scwin.gIDX_ASST_CLSS_ID + // 기초자산
        "&{P}V_IDX_LVRG_INVRS_TP_CD=" + $c.stf.getObjectValue(cmb_IDX_LVRG_INVRS_TP_CD) + // 추적배수	 
        "&{P}V_SRH_IDX_NM=" + $c.stf.getObjectValue(txb_SRH_IDX_NM); // 지수명

    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List, "유형분류 및 ETF·ETN 지수 관리", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};



/********************************************** 
 * 함수명   : fn_setParBasIdxInfo()
 * 설명       : 선택 지수정보를 셋팅해준다 
 ***********************************************/
scwin.fn_setParBasIdxInfo = async function() {
    var arrPar = new Array();
    var gRow = dts_List.getRowPosition();
    //var gVal = "";

    //alert('PPP IDX_TOTAL_CD='+dts_List.NameValue(gRow, "IDX_TOTAL_CD"));
    //alert('PPP IDX_MKT_CLSS_ID='+dts_List.NameValue(gRow, "IDX_MKT_CLSS_ID"));
    if (scwin.fn_SetPar != undefined) {
        arrPar[0] = {
            IDX_TOTAL_CD: dts_List.getCellData(gRow, "IDX_TOTAL_CD"),
            BAS_IDX_NM: dts_List.getCellData(gRow, "BAS_IDX_NM"),
            REF_IDX_NM: dts_List.getCellData(gRow, "REF_IDX_NM"),
            IDX_LVRG_INVRS_TP_NM: dts_List.getCellData(gRow, "IDX_LVRG_INVRS_TP_NM") // 추적배수
                ,
            MKT_TP_NM_L: dts_List.getCellData(gRow, "MKT_TP_NM_L") // 기초시장 대
                ,
            MKT_TP_NM_M: dts_List.getCellData(gRow, "MKT_TP_NM_M") // 기초시장 중
                ,
            MKT_TP_NM_S: dts_List.getCellData(gRow, "MKT_TP_NM_S") // 기초시장 소
                ,
            ULY_TP_NM_L1: dts_List.getCellData(gRow, "ULY_TP_NM_L1") // 기초자산1 대
                ,
            ULY_TP_NM_M1: dts_List.getCellData(gRow, "ULY_TP_NM_M1") // 기초자산1 중
                ,
            ULY_TP_NM_S1: dts_List.getCellData(gRow, "ULY_TP_NM_S1") // 기초자산1 소
                ,
            ULY_TP_NM_L2: dts_List.getCellData(gRow, "ULY_TP_NM_L2") // 기초자산2 대
                ,
            ULY_TP_NM_M2: dts_List.getCellData(gRow, "ULY_TP_NM_M2") // 기초자산2 중
                ,
            ULY_TP_NM_S2: dts_List.getCellData(gRow, "ULY_TP_NM_S2") // 기초자산2 소
                ,
            IDX_CALC_INST_CD: dts_List.getCellData(gRow, "IDX_CALC_INST_CD") // 지수산출기관
                ,
            IDX_MKT_CLSS_ID: dts_List.getCellData(gRow, "IDX_MKT_CLSS_ID") // 기초시장
                ,
            IDX_SEQ: dts_List.getCellData(gRow, "IDX_SEQ") // 일련번호
                ,
            IDX_LVRG_INVRS_TP_CD: dts_List.getCellData(gRow, "IDX_LVRG_INVRS_TP_CD") // 추적배수
                ,
            STRT_DD: dts_List.getCellData(gRow, "STRT_DD") // 시작일자
        };
        scwin.fn_SetPar(arrPar);
    }
    await $c.frame.CloseFrame();
};
scwin.cmb_MKT_TP_CD_L_OnSelChange = function() {
    scwin.gIDX_MKT_CLSS_ID_L = dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID");
    dts_MKT_TP_CD_M.UseFilter = true;
    dts_MKT_TP_CD_M.Filter();
    dts_MKT_TP_CD_M.sort("IDX_MKT_CLSS_ID", 0);
    //dts_MKT_TP_CD_M.sort(); // W-Craft 주석처리 
    if (dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") == "") {
        cmb_MKT_TP_CD_M.setSelectedIndex(0);
        cmb_MKT_TP_CD_S.setSelectedIndex(0);
    }
};
scwin.dts_MKT_TP_CD_M_OnFilter = function(row) {
    if (scwin.gIDX_MKT_CLSS_ID_L == "") {
        return true;
    } else {
        if (dts_MKT_TP_CD_M.getCellData(row, "UP_MKT_CLSS_ID") == scwin.gIDX_MKT_CLSS_ID_L || dts_MKT_TP_CD_M.getCellData(row, "IDX_MKT_CLSS_ID") == "") {
            return true;
        } else {
            return false;
        }
    }
};
