scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);

    // 초기1회 초기값으로 설정된 지수업종코드를 검색한다.
    if (scwin.strSch != "") {
        for (var i = 1; i <= dts_List.getTotalRow(); i++) {
            //if (strSch == dts_List.ColumnString(i, 1))  { // 찾아야할 코드를 발견했을 경우
            if (scwin.strSch.substring(0, 13) == dts_List.getCellData(i, "IDX_TOTAL_CD").substring(0, 13)) // 찾아야할 코드를 발견했을 경우(STRT_DD제외)

            {
                dts_List.setRowPosition(i, 0);
                break;
            }
        }
    }
};
scwin.btn_select_onclick = function() {
    scwin.fn_setParBasIdxInfo();
    //fn_ExcelDown();

};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.grd_List_OnDblClick = function(row, colid) {
    //alert('grd_List.OnDblClick('+row+','+ colid+')');
    if (row == 0) return;
    scwin.fn_setParBasIdxInfo();
};
scwin.gform_onload = function() {
    var arrPar = new Array();
    scwin.fn_init();
    $c.cm.PanelToGroupBox(panel_Top);

    /***************************************
    opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
    opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
    ***************************************/
    scwin.fn_GetPar = $c.frame.path("../").scwin.fn_GetPar;
    scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arrPar);
        scwin.strSch = (arrPar.length > 1 ? arrPar[0] : ""); // 지수전체코드정보(산출기관+시장ID+일련번호+추적배수+시작일자)  시작일자는 상황에 따라 없음

    }
    scwin.fn_list_sync();
};
scwin.txb_SRH_IDX_NM_onkeyup = function() {
    if (window.event.keyCode == 13) {
        scwin.fn_list_sync();
    }
};
